sys_hub_input_scripts.script:
{"last_password_reset_date":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
var passwordResetDate = new GlideDateTime();
return passwordResetDate.getValue();"}}

{"password_reset_process":{"scriptActive":false,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
var passwordResetProcess = fd_data.subflow_inputs.password_reset_request.process;
return passwordResetProcess;"}}

{"user":{"scriptActive":false,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
var user = fd_data.subflow_inputs.password_reset_request.user;
return user;"}}

